package vn.xuannhashop.business.reporting.application;
import java.util.*;import java.time.*;import java.math.BigDecimal;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;import vn.xuannhashop.business.shared.security.ActorContext;import vn.xuannhashop.business.shared.audit.ActivityService;
@Service public class BusinessPerformanceService implements BusinessPerformanceApplication {
    private final BusinessPerformanceRepository r;private final ActorContext actor;private final ActivityService audit;
    public BusinessPerformanceService(BusinessPerformanceRepository r,ActorContext actor,ActivityService audit){this.r=r;this.actor=actor;this.audit=audit;}
    @Transactional(readOnly=true) public Map<String,Object> report(String period){actor.require("OWNER","ACCOUNTANT");YearMonth month;try{month=YearMonth.parse(period);}catch(Exception e){throw DomainException.bad("Chọn kỳ YYYY-MM.");}if(month.isAfter(YearMonth.now(ZoneId.of("Asia/Ho_Chi_Minh")))||month.isBefore(YearMonth.of(2000,1)))throw DomainException.bad("Chọn kỳ đã bắt đầu từ năm 2000.");LocalDate start=month.atDay(1),end=month.plusMonths(1).atDay(1);var zone=ZoneId.of("Asia/Ho_Chi_Minh");var result=new LinkedHashMap<>(r.report(period,start.atStartOfDay(zone).toInstant(),end.atStartOfDay(zone).toInstant(),start,end));var financial=(Map<String,Object>)result.get("financial");BigDecimal revenue=(BigDecimal)financial.get("rental_received"),compensation=(BigDecimal)financial.get("compensation_received"),cost=(BigDecimal)financial.get("operating_expense"),wages=(BigDecimal)financial.get("payroll_cost"),depreciation=(BigDecimal)financial.get("depreciation");financial.put("management_result",revenue.add(compensation).subtract(cost).subtract(wages).subtract(depreciation));result.put("period",period);result.put("basis","Kết quả quản trị = thuê và bồi thường thực thu − chi phí hoạt động đã duyệt theo ngày phát sinh − lương đã duyệt trong kỳ (trước trừ tạm ứng) − phân bổ giá mua theo ngày. Không tính cọc là doanh thu; mua thiết bị là đầu tư, không trừ hai lần. Chưa bao gồm thuế hoặc thay thế báo cáo kế toán chuẩn. Kỳ đang mở có số liệu tạm tính.");return result;}
}
